/* ---------- Source stack ---------- */
.ssx{display:flex;flex-direction:column;gap:10px;align-items:flex-start}
.ssx-pill{display:inline-flex;align-items:center;gap:8px;height:30px;padding:0 10px 0 5px;border-radius:999px;background:var(--chip);font-size:12.5px;color:var(--fg2);transition:background .25s,color .25s}
.ssx-pill:hover{background:var(--hover);color:var(--fg)}
.ssx-pill>svg{transition:transform .4s var(--ease)}
.ssx-pill[aria-expanded="true"]>svg{transform:rotate(180deg)}
.ssx-ics{display:flex}
.ssx-ics span{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:9px;font-weight:500;color:#fff;box-shadow:0 0 0 2px var(--chip);margin-right:-6px;transition:margin .4s var(--ease)}
.ssx-pill:hover .ssx-ics span{margin-right:-3px}
.ssx-ics span:last-child{margin-right:0}
.ssx-box{width:100%}
.ssx-in{padding:2px 0 4px;display:flex;flex-direction:column;gap:8px}
.ssx-fl{display:flex;gap:4px;flex-wrap:wrap}
.ssx-fl .chip.on{background:var(--ink);color:var(--on-ink);box-shadow:none}
.ssx-list{display:flex;flex-direction:column;gap:2px;margin-inline:-6px}
.ssx-s{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:10px;font-size:13px;transition:background .25s}
.ssx-s:hover{background:var(--row)}
.ssx-s .fv{width:22px;height:22px;border-radius:7px;display:grid;place-items:center;font-size:9.5px;font-weight:500;flex:none}
.ssx-s .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ssx-s .h{font-size:12px;color:var(--muted)}
.ssx-s .rel{width:36px;height:4px;border-radius:2px;background:var(--line);overflow:hidden;flex:none}
.ssx-s .rel i{display:block;height:100%;background:var(--accent-mark,var(--accent));border-radius:2px;transform-origin:left;animation:ssrel .8s var(--ease) both}
@keyframes ssrel{from{transform:scaleX(0)}}
.ssx-s .ib{width:24px;height:24px;opacity:0;transition:opacity .2s}
.ssx-s:hover .ib{opacity:1}

DM.def('source-stack', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  const S = [
    ['web','Baymard: pricing page UX','baymard.com',.92,'B','var(--pb)'],
    ['web','Annual vs monthly anchoring study','cxl.com',.88,'C','#d9480f'],
    ['file','Q3 conversion export.csv','Drive',.84,'CSV','var(--pm)'],
    ['figma','Pricing v4, frame 2','Figma',.8,'F','var(--pl)'],
    ['web','Stripe billing docs','stripe.com',.66,'S','#635bff'],
    ['file','Pricing research notes','Notion',.61,'N','var(--fg2)'],
    ['figma','Checkout flow','Figma',.52,'F','var(--pl)'],
    ['web','NN/g on price framing','nngroup.com',.48,'N','var(--fg2)']
  ];
  const pill = $('.ssx-pill', r), box = $('.ssx-box', r), list = $('.ssx-list', r);
  $('.ssx-ics', r).innerHTML = S.slice(0, 4).map(s => `<span style="background:${s[5]}">${s[4][0]}</span>`).join('');
  function paint(f){
    const items = S.filter(s => f === 'all' || s[0] === f);
    list.innerHTML = items.map(s => `<div class="ssx-s"><span class="fv" style="background:color-mix(in srgb,${s[5]} 14%,transparent);color:${s[5]}">${s[4]}</span><span class="t">${s[1]}<span class="h"> · ${s[2]}</span></span><span class="rel" data-tip="Relevance ${Math.round(s[3] * 100)}%"><i style="width:${s[3] * 100}%"></i></span><button class="ib" aria-label="Open source" data-tip="Open">${I('ext','xs')}</button></div>`).join('');
    stagger($$('.ssx-s', list), 40);
  }
  pill.onclick = () => { const open = box.classList.toggle('shut') === false; pill.setAttribute('aria-expanded', open); if (open) paint($('.ssx-fl .on', r).dataset.f); };
  $$('.ssx-fl .chip', r).forEach(ch => ch.onclick = () => { $$('.ssx-fl .chip', r).forEach(x => x.classList.toggle('on', x === ch)); paint(ch.dataset.f); });
  c.later(1100, () => { if (pill.getAttribute('aria-expanded') === 'false') pill.click(); });
});
